   149	func (a *PiAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
   150		// Stream one JSON value rather than io.ReadAll so the hook never blocks
   151		// waiting for stdin EOF that some agents don't send on Windows (issue #1398).
   152		parsed, err := agent.ReadAndParseHookInput[piHookPayload](stdin)
   153		if err != nil {
   154			return nil, err
   155		}
   156		payload := *parsed
   157	
   158		sessionID := payload.SessionID
   159		if sessionID == "" {
   160			sessionID = extractSessionIDFromPath(payload.SessionFile)
   161		}
   162	
   163		now := time.Now()
   164	
   165		// A sessionless payload names no session we can track. It must not borrow a
   166		// repo-global session identity — see docs/architecture/agent-guide.md for how
   167		// a nested `pi --no-session` subagent thereby claimed its parent's session.
   168		//
   169		// session_shutdown is exempt: the extension sends it with no session identity at
   170		// all, and the no-op handler below preserves the contract that it is not a
   171		// SessionEnd event. Same shape as Copilot CLI's subordinate-session guard
   172		// (copilotcli/lifecycle.go).
   173		if hookName != HookNameSessionShutdown && sessionID == "" {
   174			logging.Debug(ctx, "pi: skipping lifecycle event for sessionless (nested) Pi invocation",
   175				slog.String("hook", hookName))
