   243	// resolveSessionDir returns the per-repo hook cache directory used by
   244	// captureTranscript.
   245	//
   246	// This is intentionally distinct from PiAgent.GetSessionDir, which
   247	// points at Pi's native session store (~/.pi/agent/sessions/...) so
   248	// cold attach can resolve transcripts that were never hook-captured.
   249	// The cache here is hook-internal and only reachable via Pi hooks
   250	// firing; the framework records the cached path as SessionRef in
   251	// checkpoint metadata, so subsequent operations on hooked sessions go
   252	// through the recorded path rather than re-resolving via GetSessionDir.
   253	func resolveSessionDir(ctx context.Context) (worktreeRoot string, ok bool) {
   254		root, err := paths.WorktreeRoot(ctx)
   255		if err != nil {
   256			//nolint:forbidigo // fallback when no git repo (tests run outside repos)
   257			wd, wdErr := os.Getwd()
   258			if wdErr != nil {
   259				return "", false
   260			}
   261			root = wd
   262		}
   263		return root, true
   264	}
   265	
   266	// sessionCacheDir is .entire/tmp/pi relative to the .entire root.
   267	var sessionCacheDir = entiredir.MustName(paths.EntireTmpDir) + "/" + piHookCacheSubdir
