   269	// openSessionCache returns the shared .entire root for the repo this hook is
   270	// running in, with the pi/ cache directory created under it. A repo that cannot
   271	// be resolved yields ok=false and every caller degrades: the cache is an
   272	// optimization, never the only copy of anything.
   273	func openSessionCache(ctx context.Context) (root *os.Root, ok bool) {
   274		worktreeRoot, ok := resolveSessionDir(ctx)
   275		if !ok {
   276			return nil, false
   277		}
   278		root, err := entiredir.OpenAt(worktreeRoot)
   279		if err != nil {
   280			return nil, false
   281		}
