   304	// captureTranscript copies the Pi JSONL session file to
   305	// <repo>/.entire/tmp/pi/<id>.json so Entire has a stable transcript
   306	// reference. Returns the path to the cached file, or "" if either input is
   307	// missing. The pi/ namespace under .entire/tmp/ is intentional — see
   308	// GetSessionDir / piHookCacheSubdir for the rationale.
   309	func captureTranscript(ctx context.Context, sessionID, piSessionFile string) string {
   310		if sessionID == "" || piSessionFile == "" {
   311			return ""
   312		}
   313		// sessionID comes from the hook payload and is used to build dst below,
   314		// before the lifecycle dispatcher validates it. Validate here at the choke
