   317		if err := validation.ValidateSessionID(sessionID); err != nil {
   318			logging.Warn(ctx, "pi: refusing to capture transcript for unsafe session ID",
   319				slog.String("session_id", sessionID), slog.String("err", err.Error()))
   320			return ""
   321		}
   322		worktreeRoot, ok := resolveSessionDir(ctx)
   323		if !ok {
   324			return ""
   325		}
   326		root, ok := openSessionCache(ctx)
   327		if !ok {
   328			return ""
   329		}
